class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14)

        self.previous_closes = {}
        self.spy_previous_difference = None
        self.aapl_red_streak = 0

        # Each strategy owns and accounts for only its own private lot.
        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        spy_bar = bars.get("SPY")
        if spy_bar is not None:
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)

        aapl_bar = bars.get("AAPL")
        if aapl_bar is not None:
            previous_aapl_close = self.previous_closes.get("AAPL")
            if previous_aapl_close is not None:
                if aapl_bar.Close < previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        # Market-state calculations continue even on an incomplete Slice.
        for ticker, bar in bars.items():
            self.previous_closes[ticker] = bar.Close

        if len(bars) != len(self.symbols):
            self._update_spy_cross_state(spy_bar)
            return

        # Sells are evaluated before buys. The two lots otherwise act independently.
        if self.spy_lot > 0 and self._spy_crossed_below(spy_bar):
            self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and self._spy_crossed_above(spy_bar):
            quantity = self.CalculateOrderQuantity(self.symbols["SPY"], 0.40)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            cash_to_invest = 20_000
            if self.Portfolio.Cash >= cash_to_invest:
                quantity = int(cash_to_invest // aapl_bar.Close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

        self._update_spy_cross_state(spy_bar)

    def _spy_crossed_above(self, spy_bar):
        if not self.spy_sma.IsReady or self.spy_previous_difference is None:
            return False
        current_difference = spy_bar.Close - self.spy_sma.Current.Value
        return self.spy_previous_difference <= 0 and current_difference > 0

    def _spy_crossed_below(self, spy_bar):
        if not self.spy_sma.IsReady or self.spy_previous_difference is None:
            return False
        current_difference = spy_bar.Close - self.spy_sma.Current.Value
        return self.spy_previous_difference >= 0 and current_difference < 0

    def _update_spy_cross_state(self, spy_bar):
        if spy_bar is not None and self.spy_sma.IsReady:
            self.spy_previous_difference = spy_bar.Close - self.spy_sma.Current.Value

