class DailySmaAndRsiStrategy(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.DAILY).symbol
            for ticker in self.tickers
        }

        self.spy_closes = deque(maxlen=101)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi_changes = deque(maxlen=14)
        self.aapl_average_gain = None
        self.aapl_average_loss = None
        self.aapl_rsi = None

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        if "SPY" in bars:
            self.spy_closes.append(float(bars["SPY"].close))

        if "AAPL" in bars:
            aapl_close = float(bars["AAPL"].close)
            self._update_aapl_state(aapl_close)

        if len(bars) != len(self.symbols):
            return

        self._evaluate_strategy_a(float(bars["SPY"].close))
        self._evaluate_strategy_b(float(bars["AAPL"].close))

    def _update_aapl_state(self, close):
        if self.aapl_previous_close is not None:
            change = close - self.aapl_previous_close
            if change < 0:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            gain = max(change, 0.0)
            loss = max(-change, 0.0)
            if self.aapl_average_gain is None:
                self.aapl_rsi_changes.append((gain, loss))
                if len(self.aapl_rsi_changes) == 14:
                    self.aapl_average_gain = sum(x[0] for x in self.aapl_rsi_changes) / 14
                    self.aapl_average_loss = sum(x[1] for x in self.aapl_rsi_changes) / 14
                    self.aapl_rsi = self._rsi_value()
            else:
                self.aapl_average_gain = (13 * self.aapl_average_gain + gain) / 14
                self.aapl_average_loss = (13 * self.aapl_average_loss + loss) / 14
                self.aapl_rsi = self._rsi_value()

        self.aapl_previous_close = close

    def _rsi_value(self):
        if self.aapl_average_loss == 0:
            return 100.0 if self.aapl_average_gain > 0 else 50.0
        relative_strength = self.aapl_average_gain / self.aapl_average_loss
        return 100.0 - 100.0 / (1.0 + relative_strength)

    def _evaluate_strategy_a(self, close):
        if len(self.spy_closes) < 101:
            return

        closes = list(self.spy_closes)
        previous_sma = sum(closes[:100]) / 100
        current_sma = sum(closes[1:]) / 100
        crossed_above = closes[-2] <= previous_sma and close > current_sma
        crossed_below = closes[-2] >= previous_sma and close < current_sma

        if self.strategy_a_shares > 0 and crossed_below:
            self.market_order(self.symbols["SPY"], -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_a_shares == 0 and crossed_above:
            quantity = self.calculate_order_quantity(self.symbols["SPY"], 0.40)
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.strategy_a_shares = quantity

    def _evaluate_strategy_b(self, close):
        if self.aapl_rsi is None:
            return

        if self.strategy_b_shares > 0 and self.aapl_rsi > 60:
            self.market_order(self.symbols["AAPL"], -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            cash_required = 20_000
            if float(self.portfolio.cash) >= cash_required:
                quantity = floor(cash_required / close)
                if quantity > 0:
                    self.market_order(self.symbols["AAPL"], quantity)
                    self.strategy_b_shares = quantity

