class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy_closes = deque(maxlen=101)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        # Quantities are private strategy lots, rather than aggregate holdings.
        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        bars = data.Bars

        # Market-state values continue to consume every available ticker bar,
        # even when a missing subscription prevents rule evaluation today.
        spy_bar = bars[self.symbols["SPY"]] if bars.ContainsKey(
            self.symbols["SPY"]
        ) else None
        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.Close))

        aapl_bar = bars[self.symbols["AAPL"]] if bars.ContainsKey(
            self.symbols["AAPL"]
        ) else None
        if aapl_bar is not None:
            close = float(aapl_bar.Close)
            if self.aapl_previous_close is not None:
                if close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = close
            self.aapl_rsi.Update(aapl_bar.EndTime, close)

        if any(not bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        # Sells are evaluated before buys.  Each strategy evaluates only the
        # side appropriate to whether its own lot is empty or non-empty.
        self._evaluate_spy(spy_bar)
        self._evaluate_aapl(aapl_bar)

    def _evaluate_spy(self, bar):
        if len(self.spy_closes) < 101:
            return

        closes = list(self.spy_closes)
        previous_sma = sum(closes[:-1]) / 100.0
        current_sma = sum(closes[1:]) / 100.0
        crossed_above = closes[-2] <= previous_sma and closes[-1] > current_sma
        crossed_below = closes[-2] >= previous_sma and closes[-1] < current_sma

        if self.spy_lot > 0:
            if crossed_below:
                self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0
            return

        if crossed_above:
            quantity = int(floor(
                0.40 * float(self.Portfolio.TotalPortfolioValue)
                / float(bar.Close)
            ))
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

    def _evaluate_aapl(self, bar):
        if not self.aapl_rsi.IsReady:
            return

        if self.aapl_lot > 0:
            if float(self.aapl_rsi.Current.Value) > 60.0:
                self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0
            return

        if self.aapl_red_streak >= 3 and float(self.Portfolio.Cash) >= 20000.0:
            quantity = int(floor(20000.0 / float(bar.Close)))
            if quantity > 0:
                self.MarketOrder(self.symbols["AAPL"], quantity)
                self.aapl_lot = quantity

