from collections import deque
from math import floor


class IndependentSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.tickers = ("SPY", "AAPL", "IBM", "BAC", "AIG")
        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.DAILY).symbol
            for ticker in self.tickers
        }

        # Keep market-state calculations independent of whether a strategy holds
        # a lot. 101 closes are needed to detect a cross of two 100-day SMAs.
        self.spy_closes = deque(maxlen=101)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.spy_lot = 0
        self.aapl_lot = 0

    def on_data(self, data: Slice):
        bars = {}
        for ticker in self.tickers:
            symbol = self.symbols[ticker]
            if symbol in data.bars:
                bars[ticker] = data.bars[symbol]

        # Market state is updated continuously from every bar that is present.
        if "SPY" in bars:
            self.spy_closes.append(float(bars["SPY"].close))

        if "AAPL" in bars:
            aapl_close = float(bars["AAPL"].close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.update(bars["AAPL"].end_time, aapl_close)

        # A missing daily bar for even an unused subscription suppresses every
        # strategy rule for the day.
        if len(bars) != len(self.tickers):
            return

        spy_close = float(bars["SPY"].close)
        aapl_close = float(bars["AAPL"].close)

        # Sells are evaluated before buys. Each strategy can sell only its own
        # tracked lot, and a buy reason is considered only while that lot is flat.
        if self.spy_lot > 0 and self._spy_crossed_below_sma():
            self.market_order(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and self.aapl_rsi.is_ready:
            if float(self.aapl_rsi.current.value) > 60:
                self.market_order(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0

        if self.spy_lot == 0 and self._spy_crossed_above_sma():
            quantity = floor(0.40 * float(self.portfolio.total_portfolio_value) / spy_close)
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_rsi.is_ready:
            if self.aapl_red_streak >= 3 and float(self.portfolio.cash) >= 20_000:
                quantity = floor(20_000 / aapl_close)
                if quantity > 0:
                    self.market_order(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

    def _spy_crossed_above_sma(self):
        if len(self.spy_closes) < 101:
            return False
        closes = list(self.spy_closes)
        previous_sma = sum(closes[:100]) / 100
        current_sma = sum(closes[1:]) / 100
        return closes[-2] <= previous_sma and closes[-1] > current_sma

    def _spy_crossed_below_sma(self):
        if len(self.spy_closes) < 101:
            return False
        closes = list(self.spy_closes)
        previous_sma = sum(closes[:100]) / 100
        current_sma = sum(closes[1:]) / 100
        return closes[-2] >= previous_sma and closes[-1] < current_sma

