class IndependentSmaAndRsiStrategy(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.DAILY).symbol
            for ticker in self.tickers
        }

        self.spy_closes = RollingWindow[float](101)
        self.aapl_closes = RollingWindow[float](4)
        self.aapl_rsi = self.rsi(
            self.symbols["AAPL"], 14, MovingAverageType.WILDERS, Resolution.DAILY
        )

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        spy_symbol = self.symbols["SPY"]
        aapl_symbol = self.symbols["AAPL"]
        if data.bars.contains_key(spy_symbol):
            self.spy_closes.add(float(data.bars[spy_symbol].close))
        if data.bars.contains_key(aapl_symbol):
            self.aapl_closes.add(float(data.bars[aapl_symbol].close))

        # The market-state series above continue updating, but the system is
        # evaluated only when all five of today's daily bars exist.
        if any(not data.bars.contains_key(symbol) for symbol in self.symbols.values()):
            return

        spy_close = float(data.bars[spy_symbol].close)
        aapl_close = float(data.bars[aapl_symbol].close)

        # Wait until every rolling calculation used by the rules is fully formed.
        if (
            not self.spy_closes.is_ready
            or not self.aapl_closes.is_ready
            or not self.aapl_rsi.is_ready
        ):
            return

        spy_crossed_above, spy_crossed_below = self._spy_sma_crosses()
        aapl_red_for_three = self._aapl_red_for_three_days()
        aapl_rsi = float(self.aapl_rsi.current.value)

        # Sells are evaluated before buys, independently for each strategy lot.
        if self.strategy_a_shares > 0:
            if spy_crossed_below:
                self.market_order(self.symbols["SPY"], -self.strategy_a_shares)
                self.strategy_a_shares = 0
        elif spy_crossed_above:
            quantity = int((0.40 * float(self.portfolio.total_portfolio_value)) / spy_close)
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.strategy_a_shares = quantity

        if self.strategy_b_shares > 0:
            if aapl_rsi > 60:
                self.market_order(self.symbols["AAPL"], -self.strategy_b_shares)
                self.strategy_b_shares = 0
        elif aapl_red_for_three and float(self.portfolio.cash) >= 20_000:
            quantity = int(20_000 // aapl_close)
            if quantity > 0:
                self.market_order(self.symbols["AAPL"], quantity)
                self.strategy_b_shares = quantity

    def _spy_sma_crosses(self):
        current_close = self.spy_closes[0]
        previous_close = self.spy_closes[1]
        current_sma = sum(self.spy_closes[i] for i in range(100)) / 100.0
        previous_sma = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0

        crossed_above = previous_close <= previous_sma and current_close > current_sma
        crossed_below = previous_close >= previous_sma and current_close < current_sma
        return crossed_above, crossed_below

    def _aapl_red_for_three_days(self):
        return all(
            self.aapl_closes[i] < self.aapl_closes[i + 1]
            for i in range(3)
        )

