class StrategySystemAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = RollingWindow[float](100)
        self.previous_spy_close = None
        self.previous_spy_sma = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.rsi_change_count = 0
        self.rsi_gain_sum = 0.0
        self.rsi_loss_sum = 0.0
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        self._apply_splits(data)

        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        if "SPY" in bars:
            spy_cross_above, spy_cross_below = self._update_spy(
                float(bars["SPY"].Close)
            )
        else:
            spy_cross_above = False
            spy_cross_below = False

        if "AAPL" in bars:
            self._update_aapl(float(bars["AAPL"].Close))

        if len(bars) != len(self.symbols):
            return

        spy_close = float(bars["SPY"].Close)
        aapl_close = float(bars["AAPL"].Close)

        # Strategy A: its sell is evaluated before its buy.
        if self.strategy_a_shares > 0:
            if spy_cross_below:
                self.MarketOrder(
                    self.symbols["SPY"],
                    -self.strategy_a_shares,
                    tag="Strategy A: 100-day SMA cross below",
                )
                self.strategy_a_shares = 0
        elif spy_cross_above:
            target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
            quantity = int(target_value // spy_close)
            if quantity > 0:
                self.MarketOrder(
                    self.symbols["SPY"],
                    quantity,
                    tag="Strategy A: 100-day SMA cross above",
                )
                self.strategy_a_shares = quantity

        # Strategy B: its sell is evaluated before its buy.
        if self.strategy_b_shares > 0:
            if self.aapl_rsi is not None and self.aapl_rsi > 60.0:
                self.MarketOrder(
                    self.symbols["AAPL"],
                    -self.strategy_b_shares,
                    tag="Strategy B: RSI above 60",
                )
                self.strategy_b_shares = 0
        elif self.aapl_red_streak >= 3 and float(self.Portfolio.Cash) >= 20_000.0:
            quantity = int(20_000.0 // aapl_close)
            if quantity > 0:
                self.MarketOrder(
                    self.symbols["AAPL"],
                    quantity,
                    tag="Strategy B: three consecutive red days",
                )
                self.strategy_b_shares = quantity

    def _update_spy(self, close):
        old_close = self.previous_spy_close
        old_sma = self.previous_spy_sma

        self.spy_closes.Add(close)
        current_sma = None
        if self.spy_closes.IsReady:
            current_sma = sum(self.spy_closes[i] for i in range(100)) / 100.0

        cross_above = (
            old_close is not None
            and old_sma is not None
            and current_sma is not None
            and old_close <= old_sma
            and close > current_sma
        )
        cross_below = (
            old_close is not None
            and old_sma is not None
            and current_sma is not None
            and old_close >= old_sma
            and close < current_sma
        )

        self.previous_spy_close = close
        self.previous_spy_sma = current_sma
        return cross_above, cross_below

    def _update_aapl(self, close):
        if self.previous_aapl_close is None:
            self.previous_aapl_close = close
            return

        change = close - self.previous_aapl_close
        if change < 0:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0

        gain = max(change, 0.0)
        loss = max(-change, 0.0)
        if self.rsi_change_count < 14:
            self.rsi_gain_sum += gain
            self.rsi_loss_sum += loss
            self.rsi_change_count += 1
            if self.rsi_change_count == 14:
                self.rsi_average_gain = self.rsi_gain_sum / 14.0
                self.rsi_average_loss = self.rsi_loss_sum / 14.0
        else:
            self.rsi_average_gain = (self.rsi_average_gain * 13.0 + gain) / 14.0
            self.rsi_average_loss = (self.rsi_average_loss * 13.0 + loss) / 14.0

        if self.rsi_average_gain is not None:
            if self.rsi_average_loss == 0.0:
                self.aapl_rsi = 100.0
            else:
                relative_strength = self.rsi_average_gain / self.rsi_average_loss
                self.aapl_rsi = 100.0 - 100.0 / (1.0 + relative_strength)

        self.previous_aapl_close = close

    def _apply_splits(self, data):
        for ticker, lot_name in (
            ("SPY", "strategy_a_shares"),
            ("AAPL", "strategy_b_shares"),
        ):
            symbol = self.symbols[ticker]
            if not data.Splits.ContainsKey(symbol):
                continue
            split = data.Splits[symbol]
            if split.Type != SplitType.SplitOccurred:
                continue
            shares = getattr(self, lot_name)
            if shares > 0:
                setattr(self, lot_name, int(shares / float(split.SplitFactor)))

