class StrategySystemAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.previous_closes = {}
        self.spy_closes = deque(maxlen=100)
        self.previous_spy_relation = None

        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        bars = {}
        complete_slice = True
        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                complete_slice = False
                continue
            bars[ticker] = data.Bars[symbol]

        # Market-state quantities continue to consume every available bar, even
        # when a missing subscription makes this slice ineligible for trading.
        if "SPY" in bars:
            spy_close = float(bars["SPY"].Close)
            self.spy_closes.append(spy_close)
            if len(self.spy_closes) == 100:
                spy_sma = sum(self.spy_closes) / 100.0
                if spy_close > spy_sma:
                    current_spy_relation = 1
                elif spy_close < spy_sma:
                    current_spy_relation = -1
                else:
                    current_spy_relation = 0
            else:
                current_spy_relation = None
        else:
            current_spy_relation = None

        if "AAPL" in bars:
            aapl_close = float(bars["AAPL"].Close)
            previous_aapl_close = self.previous_closes.get("AAPL")
            if previous_aapl_close is not None and aapl_close < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_rsi.Update(bars["AAPL"].EndTime, aapl_close)

        if complete_slice:
            self.EvaluateStrategyA(bars["SPY"], current_spy_relation)
            self.EvaluateStrategyB(bars["AAPL"])

        for ticker, bar in bars.items():
            self.previous_closes[ticker] = float(bar.Close)
        if current_spy_relation is not None:
            self.previous_spy_relation = current_spy_relation

    def EvaluateStrategyA(self, bar, current_relation):
        if current_relation is None or self.previous_spy_relation is None:
            return

        crossed_below = current_relation < 0 and self.previous_spy_relation >= 0
        crossed_above = current_relation > 0 and self.previous_spy_relation <= 0

        # Sells are evaluated before buys.
        if self.strategy_a_shares > 0:
            if crossed_below:
                self.MarketOrder(self.symbols["SPY"], -self.strategy_a_shares)
                self.strategy_a_shares = 0
            return

        if crossed_above:
            close = float(bar.Close)
            shares = int((0.40 * float(self.Portfolio.TotalPortfolioValue)) // close)
            if shares > 0:
                self.MarketOrder(self.symbols["SPY"], shares)
                self.strategy_a_shares = shares

    def EvaluateStrategyB(self, bar):
        # Sells are evaluated before buys.
        if self.strategy_b_shares > 0:
            if self.aapl_rsi.IsReady and float(self.aapl_rsi.Current.Value) > 60.0:
                self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_shares)
                self.strategy_b_shares = 0
            return

        if self.aapl_rsi.IsReady and self.aapl_red_streak >= 3:
            cash_to_invest = 20_000.0
            if float(self.Portfolio.Cash) >= cash_to_invest:
                shares = int(cash_to_invest // float(bar.Close))
                if shares > 0:
                    self.MarketOrder(self.symbols["AAPL"], shares)
                    self.strategy_b_shares = shares

