class IndependentDailyStrategiesAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=101)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_lot = 0
        self.aapl_lot = 0
        self.pending_orders = {}

    def OnData(self, data: Slice):
        bars = data.Bars

        # Market-state quantities advance whenever their own ticker has a bar,
        # even when another subscription is absent and trading must be skipped.
        spy_bar = bars.get(self.symbols["SPY"])
        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.Close))

        aapl_bar = bars.get(self.symbols["AAPL"])
        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        if any(bars.get(symbol) is None for symbol in self.symbols.values()):
            return

        spy_cross_up = False
        spy_cross_down = False
        if len(self.spy_closes) == 101:
            closes = list(self.spy_closes)
            previous_sma = sum(closes[:100]) / 100.0
            current_sma = sum(closes[1:]) / 100.0
            spy_cross_up = closes[-2] <= previous_sma and closes[-1] > current_sma
            spy_cross_down = closes[-2] >= previous_sma and closes[-1] < current_sma

        # Sells are evaluated before buys.
        if self.spy_lot > 0 and not self._has_pending("SPY") and spy_cross_down:
            self._submit_order("SPY", -self.spy_lot, "A-sell")

        if (
            self.aapl_lot > 0
            and not self._has_pending("AAPL")
            and self.aapl_rsi.IsReady
            and self.aapl_rsi.Current.Value > 60
        ):
            self._submit_order("AAPL", -self.aapl_lot, "B-sell")

        if self.spy_lot == 0 and not self._has_pending("SPY") and spy_cross_up:
            close = float(spy_bar.Close)
            quantity = floor(0.40 * float(self.Portfolio.TotalPortfolioValue) / close)
            if quantity > 0:
                self._submit_order("SPY", quantity, "A-buy")

        if (
            self.aapl_lot == 0
            and not self._has_pending("AAPL")
            and self.aapl_rsi.IsReady
            and self.aapl_red_streak >= 3
            and float(self.Portfolio.Cash) >= 20_000
        ):
            quantity = floor(20_000 / float(aapl_bar.Close))
            if quantity > 0:
                self._submit_order("AAPL", quantity, "B-buy")

    def _has_pending(self, ticker):
        return any(order_ticker == ticker for order_ticker in self.pending_orders.values())

    def _submit_order(self, ticker, quantity, tag):
        ticket = self.MarketOrder(self.symbols[ticker], quantity, False, tag)
        self.pending_orders[ticket.OrderId] = ticker

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status not in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            if order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.pending_orders.pop(order_event.OrderId, None)
            return

        ticker = self.pending_orders.get(order_event.OrderId)
        fill = int(order_event.FillQuantity)
        if ticker == "SPY":
            self.spy_lot += fill
        elif ticker == "AAPL":
            self.aapl_lot += fill

        if order_event.Status == OrderStatus.Filled:
            self.pending_orders.pop(order_event.OrderId, None)

