        # even if another subscription is missing and trading is skipped below.
        if spy in data.Bars:
            spy_bar = data.Bars[spy]
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
            if self.spy_sma.IsReady:
                current_side = 1 if spy_bar.Close > self.spy_sma.Current.Value else (
                    -1 if spy_bar.Close < self.spy_sma.Current.Value else 0
                )
                if self.spy_previous_side is not None:
                    spy_cross_up = self.spy_previous_side <= 0 and current_side > 0
                    spy_cross_down = self.spy_previous_side >= 0 and current_side < 0
                self.spy_previous_side = current_side

        if aapl in data.Bars:
            aapl_bar = data.Bars[aapl]
            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif aapl_bar.Close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_bar.Close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        # Every subscribed ticker must have today's completed daily bar.
        if any(symbol not in data.Bars for symbol in self.symbols.values()):
            return

        # No rule may trade until all indicators used by the system are formed.
        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_close = data.Bars[spy].Close
        aapl_close = data.Bars[aapl].Close

        # Sells are evaluated before buys.
        if self.strategy_a_shares > 0 and spy_cross_down:
            self.MarketOrder(spy, -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(aapl, -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and spy_cross_up:
            target_value = 0.40 * self.Portfolio.TotalPortfolioValue
            quantity = int(target_value // spy_close)
            if quantity > 0:
                self.MarketOrder(spy, quantity)
                self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            cash = self.Portfolio.CashBook["USD"].Amount
            if cash >= 20_000:
                quantity = int(20_000 // aapl_close)
                if quantity > 0:
                    self.MarketOrder(aapl, quantity)
                    self.strategy_b_shares = quantity

from AlgorithmImports import *
from collections import deque
from math import floor


class IndependentSmaAndRsiStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily, fillForward=False
            ).Symbol

        self.closes = {
            symbol: deque(maxlen=100) for symbol in self.symbols.values()
        }
        self.spy_lot = 0
        self.aapl_lot = 0

        self.rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

    def OnData(self, data: Slice):
        bars = data.Bars

        # Market-state inputs are updated whenever their own bar is present,
        # even on a day on which another subscription is missing.
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        previous_spy_close = None
        previous_spy_sma = None
        current_spy_sma = None
        if bars.ContainsKey(spy):
            spy_close = float(bars[spy].Close)
            if len(self.closes[spy]) == 100:
                previous_spy_close = self.closes[spy][-1]
                previous_spy_sma = sum(self.closes[spy]) / 100.0
            self.closes[spy].append(spy_close)
            if len(self.closes[spy]) == 100:
                current_spy_sma = sum(self.closes[spy]) / 100.0

        if bars.ContainsKey(aapl):
            aapl_close = float(bars[aapl].Close)
            self.closes[aapl].append(aapl_close)
            self.rsi.Update(data.Time, aapl_close)

        for ticker in ("IBM", "BAC", "AIG"):
            symbol = self.symbols[ticker]
            if bars.ContainsKey(symbol):
                self.closes[symbol].append(float(bars[symbol].Close))

        # No strategy rule is evaluated unless every subscription has a bar.
        if any(not bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        # Strategy A: sell before buy, with the two directions of the SMA cross.
        if previous_spy_sma is not None and current_spy_sma is not None:
            crossed_below = (
                previous_spy_close >= previous_spy_sma
                and spy_close < current_spy_sma
            )
            crossed_above = (
                previous_spy_close <= previous_spy_sma
                and spy_close > current_spy_sma
            )

            if self.spy_lot > 0 and crossed_below:
                self.MarketOrder(spy, -self.spy_lot)
                self.spy_lot = 0

            if self.spy_lot == 0 and crossed_above:
                quantity = self.CalculateOrderQuantity(spy, 0.40)
                if quantity > 0:
                    self.MarketOrder(spy, quantity)
                    self.spy_lot = quantity

        # Strategy B: its red streak is the suffix of the stored AAPL closes.
        if self.rsi.IsReady and len(self.closes[aapl]) >= 4:
            aapl_closes = self.closes[aapl]
            red_for_three = (
                aapl_closes[-1] < aapl_closes[-2]
                and aapl_closes[-2] < aapl_closes[-3]
                and aapl_closes[-3] < aapl_closes[-4]
            )

            if self.aapl_lot > 0 and self.rsi.Current.Value > 60:
                self.MarketOrder(aapl, -self.aapl_lot)
                self.aapl_lot = 0

            if self.aapl_lot == 0 and red_for_three:
                cash = float(self.Portfolio.CashBook["USD"].Amount)
                if cash >= 20_000:
                    quantity = floor(20_000 / aapl_close)
                    if quantity > 0:
                        self.MarketOrder(aapl, quantity)
                        self.aapl_lot = quantity

from AlgorithmImports import *
from collections import deque
from math import floor


class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=100)
        self.spy_previous_difference = None
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.aapl_previous_rsi = None

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        spy_cross_up = False
        spy_cross_down = False
        if "SPY" in bars:
            spy_close = float(bars["SPY"].Close)
            self.spy_closes.append(spy_close)
            if len(self.spy_closes) == 100:
                difference = spy_close - sum(self.spy_closes) / 100.0
                if self.spy_previous_difference is not None:
                    spy_cross_up = (
                        self.spy_previous_difference <= 0 and difference > 0
                    )
                    spy_cross_down = (
                        self.spy_previous_difference >= 0 and difference < 0
                    )
                self.spy_previous_difference = difference

        if "AAPL" in bars:
            aapl_bar = bars["AAPL"]
            aapl_close = float(aapl_bar.Close)
            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close

            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)
            current_rsi = None
            if self.aapl_rsi.IsReady:
                current_rsi = float(self.aapl_rsi.Current.Value)

        # Every subscribed ticker must have a bar before either strategy can act.
        if len(bars) != len(self.symbols):
            if "AAPL" in bars and current_rsi is not None:
                self.aapl_previous_rsi = current_rsi
            return

        # Sells are evaluated before buys.
        if self.spy_lot > 0 and spy_cross_down:
            self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

        if (
            self.aapl_lot > 0
            and current_rsi is not None
            and self.aapl_previous_rsi is not None
            and self.aapl_previous_rsi <= 60
            and current_rsi > 60
        ):
            self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_cross_up:
            quantity = self.CalculateOrderQuantity(self.symbols["SPY"], 0.40)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        if (
            self.aapl_lot == 0
            and self.aapl_red_streak >= 3
            and self.aapl_rsi.IsReady
            and self.Portfolio.Cash >= 20_000
        ):
            quantity = floor(20_000 / float(bars["AAPL"].Close))
            if quantity > 0:
                self.MarketOrder(self.symbols["AAPL"], quantity)
                self.aapl_lot = quantity

        if current_rsi is not None:
            self.aapl_previous_rsi = current_rsi
